# Synonym resolution - merge entities with same canonical form
entities = state.get('entities', [])
if isinstance(entities, str):
    # Parse from LLM text output
    parsed = []
    for line in entities.strip().split('\n'):
        line = line.strip()
        if '|' not in line or line.startswith('Entity'):
            continue
        parts = line.split('|')
        if len(parts) >= 2:
            entity_type = parts[0].strip()
            name = parts[1].strip()
            if entity_type in ('Chemical', 'Disease') and name:
                parsed.append({'type': entity_type, 'name': name, 'canonical': name.lower().replace('-', ' ')})
    entities = parsed

# Group by canonical form and resolve synonyms
canonical = {}
for e in entities:
    if isinstance(e, dict):
        key = (e.get('type', ''), e.get('canonical', e.get('name', '').lower()))
        if key not in canonical:
            canonical[key] = {'type': e['type'], 'names': set(), 'canonical': key[1]}
        canonical[key]['names'].add(e.get('name', e.get('canonical', '')))

result = []
for k, v in canonical.items():
    # Use shortest name as representative
    rep = min(v['names'], key=len) if v['names'] else k[1]
    result.append({'type': v['type'], 'name': rep, 'canonical': v['canonical'], 'synonyms': list(v['names'])})

__result__ = result
